"""Pydantic schemas for structured generation in the FORGE orchestration engine."""

from __future__ import annotations

from typing import List
from pydantic import BaseModel, Field, field_validator


class InvestigationQuery(BaseModel):
    """Structured query generated by the Investigator LLM for dense and lexical code search."""

    query_text: str = Field(
        ...,
        description="Dense semantic search query describing the technical objective or concept.",
    )
    exact_keywords: List[str] = Field(
        default_factory=list,
        description="Exact variable names, function names, class names, or error tokens for BM25 matching.",
    )
    rationale: str = Field(
        ...,
        description="Why this specific query resolves gaps in previous findings.",
    )


class InvestigationEvaluation(BaseModel):
    """Self-evaluation critique generated by the Investigator to assess retrieval sufficiency."""

    is_sufficient: bool = Field(
        ...,
        description="True if the retrieved code contains the complete root cause, enclosing context, and references needed to write a patch; False otherwise.",
    )
    missing_symbols_or_files: List[str] = Field(
        default_factory=list,
        description="Specific missing imports, callers, callee functions, or file paths still needed.",
    )
    critique: str = Field(
        ...,
        description="Why current context is insufficient or what ambiguity remains.",
    )
    suggested_next_query: str = Field(
        default="",
        description="Proposed refined query if is_sufficient is False.",
    )


class ImplementationPlan(BaseModel):
    """Structured implementation plan generated by the Planner LLM.

    Immutable contract: Must contain valid target files, actionable logic steps,
    and a defined verification strategy.
    """

    target_files: List[str] = Field(
        ...,
        description="List of target file paths to inspect or modify",
    )
    logic_steps: List[str] = Field(
        ...,
        description="Step-by-step implementation actions to accomplish the objective",
    )
    test_strategy: str = Field(
        ...,
        description="Strategy for testing and verifying the implementation with unit tests",
    )
    reproduction_test_code: str = Field(
        default="",
        description="Self-contained Python pytest test code (tests/_forge_repro_test.py) that isolates the failure and proves the bug exists.",
    )

    @field_validator("target_files")
    @classmethod
    def validate_target_files(cls, files: List[str]) -> List[str]:
        if not files:
            raise ValueError("ImplementationPlan requires at least one target file.")
        cleaned = [f.strip().replace("\\", "/") for f in files if f and f.strip()]
        if not cleaned:
            raise ValueError("ImplementationPlan target_files must not be empty strings.")
        return cleaned

    @field_validator("logic_steps")
    @classmethod
    def validate_logic_steps(cls, steps: List[str]) -> List[str]:
        if not steps:
            raise ValueError("ImplementationPlan requires at least one logic step.")
        cleaned = [s.strip() for s in steps if s and s.strip()]
        if not cleaned:
            raise ValueError("ImplementationPlan logic_steps must contain valid text.")
        return cleaned

    @field_validator("test_strategy")
    @classmethod
    def validate_test_strategy(cls, strat: str) -> str:
        if not strat or not strat.strip():
            raise ValueError("ImplementationPlan requires a non-empty test_strategy.")
        return strat.strip()


class InvestigatorContract(BaseModel):
    """Immutable handover contract from Investigator to Implementer.

    Guarantees that target files have been explored and required symbols resolved.
    """

    target_files: List[str] = Field(
        ...,
        description="Target files committed to in the ImplementationPlan.",
    )
    resolved_symbols: List[str] = Field(
        default_factory=list,
        description="List of symbols and context chunks resolved during investigation.",
    )
    unresolved_symbols: List[str] = Field(
        default_factory=list,
        description="Any remaining missing symbols, if sufficiency could not be reached within budget.",
    )
    is_contract_fulfilled: bool = Field(
        default=True,
        description="True if all primary target symbols have corresponding context retrieved.",
    )
    handover_notes: str = Field(
        default="",
        description="Detailed technical synthesis guiding the Implementer persona.",
    )


class CodePatch(BaseModel):
    """Unified git patch generated by the Implementer LLM."""

    file_path: str = Field(
        description="Path of the target file being created or modified",
    )
    unified_diff: str = Field(
        description="Strictly formatted Unified Git Diff (starting with --- and +++ or diff --git)",
    )


class ReviewDecision(BaseModel):
    """Security audit decision generated by the Security Reviewer LLM."""

    is_approved: bool = Field(
        description="True if the patch meets security and quality requirements, False if rejected",
    )
    feedback: str = Field(
        description="Detailed review feedback explaining the approval or rejection",
    )
